import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, Edit, Trash2, CheckCircle, Clock } from 'lucide-react';
import { useAuth } from '../../context/AuthContext';
import toast from 'react-hot-toast';

const InternalManageCars = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [cars, setCars] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    // Load local storage cars (prototype simulation)
    const localCars = JSON.parse(localStorage.getItem('storeCar_published_cars')) || [];
    setCars(localCars);
  }, []);

  const handleMarkAsSold = (id) => {
    const updatedCars = cars.map(car => {
      if (car.id === id) {
        return { ...car, isInternalStatus: 'sold' };
      }
      return car;
    });

    setCars(updatedCars);
    localStorage.setItem('storeCar_published_cars', JSON.stringify(updatedCars));
    toast.success('Đánh dấu xe là Đã Bán thành công!');
  };

  const handleDelete = (id) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa tin đăng này vĩnh viễn?')) {
      const updatedCars = cars.filter(car => car.id !== id);
      setCars(updatedCars);
      localStorage.setItem('storeCar_published_cars', JSON.stringify(updatedCars));
      toast.success('Đã xóa tin đăng!');
    }
  };

  const filteredCars = cars.filter(car => 
    car.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    car.location.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-gray-50 py-10 px-4">
      <div className="max-w-7xl mx-auto">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-3xl font-extrabold text-gray-800 tracking-tight">Quản Lý Kho Xe Nôi Bộ</h1>
            <p className="text-gray-500 mt-2 text-sm">Danh sách các xe đang chạy trên ứng dụng Store Car</p>
          </div>
          <button 
            onClick={() => navigate('/internal/post-car')}
            className="bg-[#0096ff] text-white px-5 py-2.5 rounded-lg font-semibold hover:bg-blue-600 transition shadow"
          >
            + Đăng Xe Mới
          </button>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
          {/* Toolbar */}
          <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
            <div className="relative w-full max-w-sm">
              <Search size={18} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
              <input 
                type="text"
                placeholder="Tìm kiếm theo Tên xe, Vị trí..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:outline-none focus:border-[#0096ff] transition"
              />
            </div>
            <div className="text-sm font-semibold text-gray-600 bg-white px-3 py-1.5 rounded border border-gray-200">
              Tổng số: {filteredCars.length} xe
            </div>
          </div>

          {/* Data Table */}
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 text-gray-500 text-xs uppercase tracking-wider">
                  <th className="p-4 font-bold border-b border-gray-100">Hình ảnh</th>
                  <th className="p-4 font-bold border-b border-gray-100">Thông tin xe</th>
                  <th className="p-4 font-bold border-b border-gray-100">Giá đề xuất</th>
                  <th className="p-4 font-bold border-b border-gray-100">Trạng thái</th>
                  <th className="p-4 font-bold border-b border-gray-100 text-right">Thao tác</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filteredCars.length > 0 ? (
                  filteredCars.map((car) => (
                    <tr key={car.id} className="hover:bg-blue-50/20 transition-colors">
                      <td className="p-4">
                        <div className="w-20 h-14 rounded overflow-hidden border border-gray-200 shadow-sm relative">
                          <img src={car.image} alt={car.title} className="w-full h-full object-cover" />
                          {car.isInternalStatus === 'sold' && (
                            <div className="absolute inset-0 bg-gray-900/40 flex items-center justify-center">
                              <span className="text-[10px] font-bold text-white uppercase transform -rotate-12 bg-red-500/80 px-1 rounded">SOLD</span>
                            </div>
                          )}
                        </div>
                      </td>
                      <td className="p-4">
                        <div className="font-bold text-gray-800 text-[15px] mb-1">{car.title}</div>
                        <div className="text-xs text-gray-500 flex items-center gap-2">
                           <span>{car.location}</span>
                           <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                           <span>{car.mileage}</span>
                        </div>
                      </td>
                      <td className="p-4 font-bold text-[15px] text-[#0096ff]">
                        {car.highestBid}
                      </td>
                      <td className="p-4">
                        {car.isInternalStatus === 'sold' ? (
                          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold bg-gray-100 text-gray-600 border border-gray-200">
                            <CheckCircle size={14} /> Đã Bán
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold bg-[#00d68f]/10 text-[#00d68f] border border-[#00d68f]/20">
                            <span className="w-2 h-2 rounded-full bg-[#00d68f]"></span> Đang hiển thị (WEB)
                          </span>
                        )}
                      </td>
                      <td className="p-4 text-right">
                        <div className="flex justify-end gap-2">
                          {car.isInternalStatus !== 'sold' && (
                            <button 
                              onClick={() => handleMarkAsSold(car.id)}
                              className="text-xs font-bold px-3 py-1.5 bg-red-50 text-red-600 border border-red-200 rounded hover:bg-red-500 hover:text-white transition"
                              title="Tắt khỏi trang WEB"
                            >
                              Báo Đã Bán
                            </button>
                          )}
                          <button 
                            onClick={() => handleDelete(car.id)}
                            className="p-1.5 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded transition"
                            title="Xóa vĩnh viễn"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="5" className="p-10 text-center text-gray-500">
                      Chưa có xe nào được lưu trong kho của bạn.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
};

export default InternalManageCars;
